INNER JOIN user_card uc ON c.card_id = uc.card_id
WHERE uc.user_id = #{userId}
AND uc.is_deleted = false
ORDER BY c.card_id, b.benefit_id;

select EXISTS(
    select 1 from card_company where company_name=#{cardCompanyName}
)

SELECT EXISTS (
    SELECT 1
    FROM card
    WHERE card_id = #{cardId}
)

SELECT EXISTS (
    SELECT 1
    FROM user_card
    WHERE user_id = #{userId}
      AND card_id = #{cardId}
      AND is_deleted = true
)

mapper.update:
UPDATE card
SET deleted_at = NOW(), is_deleted = true
WHERE card_id = #{cardId}

mapper.select:

INNER JOIN user_card uc ON c.card_id = uc.card_id
INNER JOIN benefit_partner bp ON b.benefit_id = bp.benefit_id
WHERE uc.user_id = #{userId}
AND uc.is_deleted = false
AND bp.partner_id = #{partnerId}
ORDER BY c.card_id, b.benefit_id;
